import {scenes, failures} from './episode.js';
export const VERSION=1, EPISODE='afternoon-v1';
export const factDefaults={entryStyle:null,approach:null,hasLedgerCopy:false,repairStyle:null,publicTruth:false,alderVisited:false,bellSeal:false,alderNote:false};
export const defaultSettings={music:0.25,effects:0.45,muted:true,instant:false,reduced:false};
const copy=x=>structuredClone(x);
export function fresh(discoveries={scenesSeen:[],failuresSeen:[],endingsSeen:[]},settings=defaultSettings){const state={schemaVersion:VERSION,episodeId:EPISODE,scene:'S00',beat:0,phase:'dialogue',facts:{...factDefaults},discoveries:copy(discoveries),settings:{...settings},checkpoints:{},route:null,retryPoint:null};return enter(state,'S00');}
function remember(list,id){if(!list.includes(id))list.push(id);}
function snapshot(s){return {scene:s.scene,beat:s.beat,phase:s.phase,facts:copy(s.facts),route:copy(s.route)};}
export function enter(state,id){const s=copy(state), scene=scenes[id];if(!scene)throw Error('Unknown scene '+id);s.scene=id;s.beat=0;s.phase='dialogue';s.route=null;s.retryPoint=null;Object.assign(s.facts,scene.effects||{});remember(s.discoveries.scenesSeen,id);s.checkpoints[id]=snapshot(s);return s;}
export function lines(s){if(s.phase==='response')return scenes[s.scene].choices.find(c=>c.id===s.route.choice).response;return scenes[s.scene].lines;}
export function lineText(line,facts){return typeof line.text==='function'?line.text(facts):line.text;}
export function endingFor(f){return f.publicTruth?'E_TRUTH':f.hasLedgerCopy?'E_PAPER':'E_APPRENTICE';}
export function advance(state){const s=copy(state),scene=scenes[s.scene];if(!['dialogue','response'].includes(s.phase))return s;const sequence=lines(s);if(s.beat+1<sequence.length){s.beat++;return s;}if(s.phase==='response'){const c=scene.choices.find(c=>c.id===s.route.choice);return enter(s,c.next==='ENDING'?endingFor(s.facts):c.next);}if(scene.ending){s.phase='ending';remember(s.discoveries.endingsSeen,s.scene);return s;}if(scene.choices){s.phase='choice';s.beat=scene.lines.length;return s;}return enter(s,scene.next);}
export function choose(state,id){if(state.phase!=='choice')return state;const c=scenes[state.scene].choices.find(x=>x.id===id);if(!c)throw Error('Choice is not available');const s=copy(state);if(c.failure){s.retryPoint=snapshot(state);s.phase='failure';s.route={failure:c.failure,choice:id};remember(s.discoveries.failuresSeen,c.failure);return s;}Object.assign(s.facts,c.effects||{});s.route={choice:id};s.beat=0;if(c.response?.length){s.phase='response';return s;}return enter(s,c.next==='ENDING'?endingFor(s.facts):c.next);}
export function retry(state){if(state.phase!=='failure'||!state.retryPoint)return state;const s=copy(state);Object.assign(s,copy(state.retryPoint));s.retryPoint=null;return s;}
export function replay(state,id){const point=state.checkpoints[id];if(!point)throw Error('Checkpoint not discovered');const s=copy(state);Object.assign(s,copy(point));s.retryPoint=null;return s;}
function validFacts(f){return f&&Object.keys(factDefaults).every(k=>k in f)&&[null,'honest','bluff'].includes(f.entryStyle)&&[null,'listen','inspect'].includes(f.approach)&&[null,'mend','brace'].includes(f.repairStyle)&&['hasLedgerCopy','publicTruth','alderVisited','bellSeal','alderNote'].every(k=>typeof f[k]==='boolean');}
function validPoint(p){if(!p||!scenes[p.scene]||!validFacts(p.facts)||!Number.isInteger(p.beat)||p.beat<0)return false;const scene=scenes[p.scene];if(p.phase==='dialogue')return p.beat<scene.lines.length;if(p.phase==='choice')return !!scene.choices&&p.beat===scene.lines.length;if(p.phase==='ending')return !!scene.ending;if(p.phase==='response'){const c=scene.choices?.find(c=>c.id===p.route?.choice&&!c.failure);return !!c?.response&&p.beat<c.response.length;}if(p.phase==='failure')return !!failures[p.route?.failure]&&scene.choices?.some(c=>c.id===p.route.choice&&c.failure===p.route.failure);return false;}
export function validateSave(s){if(!s||s.schemaVersion!==VERSION||s.episodeId!==EPISODE||!validPoint(s))return false;if(!s.settings||!['music','effects'].every(k=>Number.isFinite(s.settings[k])&&s.settings[k]>=0&&s.settings[k]<=1)||!['muted','instant','reduced'].every(k=>typeof s.settings[k]==='boolean'))return false;const d=s.discoveries;if(!d||!['scenesSeen','failuresSeen','endingsSeen'].every(k=>Array.isArray(d[k])))return false;if(!d.scenesSeen.every(id=>!!scenes[id])||!d.failuresSeen.every(id=>!!failures[id])||!d.endingsSeen.every(id=>!!scenes[id]?.ending))return false;if(!s.checkpoints||!Object.entries(s.checkpoints).every(([id,p])=>p.scene===id&&p.phase==='dialogue'&&p.beat===0&&validPoint(p)))return false;if(s.phase==='failure'&&(!validPoint(s.retryPoint)||s.retryPoint.phase!=='choice'||s.retryPoint.scene!==s.scene))return false;return true;}
